cat > "$S/scripts/cfetch.js" <<'EOF'
// usage: node cfetch.js outdir name=search:WORDS | name=file:File:NAME ...
const fs=require('fs'),path=require('path');
const out=process.argv[2];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
 for(const a of process.argv.slice(3)){
  const i=a.indexOf('=');const name=a.slice(0,i);const spec=a.slice(i+1);
  let url;
  if(spec.startsWith('search:')) url='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(spec.slice(7))+'&gsrnamespace=6&gsrlimit=12&prop=imageinfo&iiprop=url%7Cextmetadata%7Csize%7Cmime&iiurlwidth=1280&format=json';
  else url='https://commons.wikimedia.org/w/api.php?action=query&titles='+encodeURIComponent(spec.slice(5))+'&prop=imageinfo&iiprop=url%7Cextmetadata%7Csize%7Cmime&iiurlwidth=1280&format=json';
  let ok=false;
  for(let t=0;t<6&&!ok;t++){
   try{const r=await fetch(url,{headers:{'User-Agent':'petct-site-research/1.0'}});const txt=await r.text();
    if(txt.trim().startsWith('{')){fs.writeFileSync(path.join(out,name+'.json'),txt);ok=true;console.log('ok',name);}
    else{console.log('retry',name,r.status);await sleep(8000*(t+1));}
   }catch(e){console.log('err',name,e.message);await sleep(8000);}
  }
  await sleep(2500);
 }
})();
EOF
cd "$S/commons"
node "$S/scripts/cfetch.js" . "hevesy=search:George de Hevesy" "hevesy2=search:Hevesy Paneth" "positron=search:positron Anderson cloud chamber" "anderson=search:Carl D. Anderson physicist"
node "$S/scripts/csum.js" hevesy.json hevesy2.json positron.json anderson.json

